#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-10-30
// ============================================================================
// docs/DEMO_PRODUCTION.md names only paths that exist
// ============================================================================
// WHAT THIS GUARDS
//
//   The Quick Start copied orchestkit-demos/scripts/demo-cli.ts into
//   plugins/ork/skills/demo-producer/src/components/configs/, a folder that
//   does not exist, and the File Organization tree drew that folder too
//   (#4793). The compositions live in orchestkit-demos/src/, where the
//   config is used in place.
//
//   Fails if: any repo path in the guide that starts with orchestkit-demos/
//   or plugins/ does not exist in the tree. Render outputs (out/) and audio
//   inputs are not repo paths and are not checked.
// ============================================================================

import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const DOC = path.join(ROOT, 'docs', 'DEMO_PRODUCTION.md');
const text = readFileSync(DOC, 'utf8');

const seen = new Set();
const failures = [];
for (const m of text.matchAll(/(?:^|[\s`(])((?:orchestkit-demos|plugins)\/[\w./-]*[\w/])/gm)) {
  const rel = m[1].replace(/\/$/, '');
  if (seen.has(rel)) continue;
  seen.add(rel);
  if (!existsSync(path.join(ROOT, rel))) failures.push(`docs/DEMO_PRODUCTION.md names ${m[1]}, which does not exist`);
}

if (seen.size === 0) failures.push('no orchestkit-demos/ or plugins/ path found in docs/DEMO_PRODUCTION.md; the scan read nothing');
for (const f of failures) console.log(`FAIL: ${f}`);
if (failures.length) process.exit(1);
console.log(`PASS: all ${seen.size} repo paths in docs/DEMO_PRODUCTION.md exist`);
